-- Admin-configurable weekly consumables alerts (non-secret settings).
-- Apply to Supabase (SQL editor or migration runner) before using alert settings in production.
-- Secrets (bot tokens) remain in env; this row holds thresholds, buckets, and routing overrides.

CREATE TABLE IF NOT EXISTS "consumables_alert_settings" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  -- Approaching band: stock > min AND stock <= min × approaching_ratio
  "approaching_ratio" REAL NOT NULL DEFAULT 1.25,
  -- When false, scheduled cron skips; admin manual run still allowed
  "weekly_enabled" BOOLEAN NOT NULL DEFAULT true,
  -- Which sections appear in the Jira/Slack weekly report
  "include_out_of_stock" BOOLEAN NOT NULL DEFAULT true,
  "include_below_minimum" BOOLEAN NOT NULL DEFAULT true,
  "include_approaching" BOOLEAN NOT NULL DEFAULT true,
  "include_good" BOOLEAN NOT NULL DEFAULT true,
  -- Display / intent for schedule (Vercel cron must match for auto-run)
  -- 1=Monday … 7=Sunday (ISO weekday)
  "schedule_weekday" INTEGER NOT NULL DEFAULT 1,
  -- Hour in America/Denver (0–23); default 8 = 8:00am MST
  "schedule_hour_mst" INTEGER NOT NULL DEFAULT 8,
  -- Optional overrides; empty means fall back to env defaults
  "slack_channel_id" TEXT NOT NULL DEFAULT '',
  "slack_ping_user_id" TEXT NOT NULL DEFAULT '',
  "jira_project_key" TEXT NOT NULL DEFAULT '',
  "jira_issue_type" TEXT NOT NULL DEFAULT '',
  "updated_by" TEXT NOT NULL DEFAULT '',
  "updated_at" TIMESTAMPTZ DEFAULT now(),
  "created_at" TIMESTAMPTZ DEFAULT now(),
  PRIMARY KEY ("id")
);
